      regs_ok (ENVb vals) srGL R ->
      (forall lo hi, (lo <= LEN <= hi)%Z -> know_ok RSEGS (ENVb vals) M (knG lo hi)) ->
      above M -> block_range L A1 CAP ->
      rdn RSEGS M (Z_to_bv 64 A1) (length fdata) = Some fdata ->
